) AS (
  VALUES 
    (434::BIGINT, 'El profe es una teja, logra hacer una materia tan aburrida como Costos sea interesantona, casi seguro es la mejor opción que va a haber en su matricula.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, '30d20bf994d553f767305e250c243b8494d5be94c12b934c00a10bbf303ff180'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'Es posiblemente el curso más pesado de la carrera, el profe es muy chill'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'f3c411948ebd4e1ef7565c327b3fc68ef4977dff87503439b0051fc6f9d3c911'::TEXT, ARRAY[1776]::BIGINT[]),
    (434::BIGINT, 'No se aprende nada, además la asistente se le olvida que fue estudiante y baja demasiados puntos en los laboratorios, tal vez para costos funcione, pero para estudio del trabajo que es practicamente la base de la carrera deja bases demasiado débiles.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '27e9b407077eb9a6e63c403db8fae4e70b3cac94d3133ecd11d94ffc9ed6f03a'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente profe y excelente persona. El asistente es el que revisa, entonces todo depende de qué tan exigente sea. Matricúle con él, y no falte a clases. Los exámenes son GAAP asincrónicos. Consígase bien grupo de trabajo, casi todo se evalúa grupalmente y no puede cambiarse'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-12T00:00:00+00:00'::TIMESTAMPTZ, '2783a9d5a9d073adcc1c741f23e7db7299c51557ce6c7a7d7a5128733ea6c050'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'El mejor profe de la AEPI, nos dio puntos por atender charlas y hasta nos llevo de gira a una empresa 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2025-08-10T00:00:00+00:00'::TIMESTAMPTZ, '3a93fc7158a42a7f20833382e9842a4aa3157c7429c575708918cd27d427ccf6'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'Auxilio, el profe es X. Pero la señora que tiene como asistente, la que califica todo, laboratorios y proyectos, esa señora revisa sangrías y puntos, nada de contenido y ni los profes de comunicación escrita se atrevieron a tanto, el profe se lava las manos y dice que se arreglen con ella.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'aa148d8cbd85b132bf78e9aaa724128ed3d84f597d16d8ff83c0bc83a4caa93b'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El curso es algo aburrido para ser una electiva, el profe es muy amable y siempre esta anuente a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '3f3a8e6f9ddaf749a271d8a435b75bf98b959ceea126d6b21b69284a21f76e02'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'El curso es un regalo, si necesita un curso facil, en la noche y que ahi medio vea procesos sirve. No es la electiva mas interesante ni donde mas se aprenda, pero es facil y muy llevadera. El profe es una teja y tampoco es estricto con la asistencia. No hay fechas de nada y se le va pero da tiempo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9a610fd50640b476c46b63b0423bbb9a5bfa4074fd54202366f26d3582beb81'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'El profe es bueno, pero es un poco aburrido entonces uno se pierde en las clases. Siempre ayuda y es super flexible con entregas y evaluaciones. En general es buena opción y da lo mejor de él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos proyectos grupales']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'a2b49f988991be72afa420631a68790f1cd161fac5975701404e312c1be744dd'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'Buena gente, es la primera vez que daba el curso y si estaba un toque perdido. Pero la verdad ayudó bastante. El proyecto es con la guía del TFG pero si tiene cualquier duda se puede quedar después de clase y revisa el trabajo completo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '337f6e1a103a8ea0d0f04d9ee8aadca37f800d8d5678f7d97bfa2d60aa4381cc'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'Es un excelente profesor, realmente se aprende de buena manera y facil. Califica binario'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1ff41c3b5d4e1207f265a20bbf27d1656e78dfe9042477c6edbabaa615150a4c'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'Dio el curso las últimas 4-5 semanas, muy buen profe. Deja todo muy claro para poder ir preparado a los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '181a3dd4ac63419ad90074508661e24bd113fdac163a2eed672f765e97e88123'::TEXT, ARRAY[1722]::BIGINT[]),
    (434::BIGINT, 'Si lo lleva con él va a ser un curso colchó, súper facil de pasar y las evaluaciones son regaladas. Es un curso realmente interesante si le pone atención. Recomendado 100%. Eso si, la asistencia es obligatoria.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd95a715cf6b9463154c73e802a240324e32f6eb613b85cd8ad152be002989c8e'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'El curso en sí es sencillo, pero al llevarlo con Harold se vuelve un curso colchón, pocas evaluaciones y muy sencillas. No lo piense y matricule con él de una.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3417aab47bdfe70cc60e539a3780c439a16ce85581d33e6717ce89513b5a938d'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'Hace el curso fácil y deja las evaluaciones para hacer en la casa. Cero pesado llevarlo en verano. Entrega las notas hasta el final. Lo malo es que no siento que se aprenda mucho con él'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'c92169834f7687bfdad12d1c6eb7b03ca941a00c93558bfe6675d2044c73dc0f'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'Realmente considero que aprendí bastante con él, me gustó la forma de explicar y a pesar de que a veces podía estar ocupado, siempre trató de ayudar en toda forma posible. Los trabajos pueden llegar a ser pesados, pero se aprende, aunque se califique a matar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-03T00:00:00+00:00'::TIMESTAMPTZ, '61c7a37d24ef824213e3979c2bbb6d6c3cefe78ebc5633bee12b787d98c64b4e'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Buena nota'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f16bbff27923d4c7776622e59c141ed59de82360f58f51072cb7d1d846d2c187'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'la clase es aburrida, pero es por la materia. Es probable que no se hagan evaluaciones importantes. El profe es muy buena nota, lo recomiendo para dirección de personal pero para otros cursos claves en la carrera definitivamente no.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'fd85fb8858b6799222e0df5cc122fba8fa6806b863ec0d038a729012d16ba4d8'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'Muy fácil pasar con él, buen profe y excelente persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '73a4d18849d2c2035d96891c0a97c4c9af775853f2781d3ba43d3a61b961fa37'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'La verdad este último semestre calificó bastante duro, le dió demasiada importancia a la gramatica y ortografía.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '56effd0bd7a4b868872245fa94f618e0f96c3a22fbcb7e08fd52331ff192f613'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'deed3400abb1ffdf3893bd36ed5b2e384332b7c4a5b0d68abe991dab7796976f'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'Creo que el profe pasa muy ocupado con sus actividades de director y por ellos es un poco despistado con respecto al curso, pero igual es super sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'ce255ec6f3adc51f3d3417e6033ae6cc83a84a11f12b6124874e2e8efffbbc68'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'El curso es muy aburrido pero sencillo. El profe no es muy exigente es cuanto a evaluaciones, es un curso que facilmente se pasa con 100'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-25T00:00:00+00:00'::TIMESTAMPTZ, '1d8b5eaddd390892305f71766d4a06458b793218adf19112123844bdaef1c39a'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'El curso es muy sencillo, se aprende lo necesario, en si el profe no es malo pero califica en semana 18 y a todo le pone 100. Laboratorios largos, TENGA UN BUEN EQUIPO DE TRABAJO porque todo es con un solo grupo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '55181d5fe12d5f37776c8ee4d31052f02516761fe69774c0cdbb4e52e9c33560'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Con él no se aprende absolutamente nada. Es muy desordenado, califica todo hasta semana 18 pero eso ayuda porque casi siempre pone 100 y no responde mensajes nunca. Con él de fijo se pasa, solo que los laboratorios son un poco largos.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '7d735043e6fffd487ef32a196bef9342ca219b9f9f688fe520da60417420d7d7'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Uno no aprende mucho, el profe pasa muy ocupado por lo que cuesta que conseguir campo para consulta y dura mucho respondiendo los mensajes. El curso se pasa solo, en semana 18 califica todo con 100 si uno lo presento.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a5f50ceac5b0d4e61ad6d462f4a64ee7130085f60ba711c20564df06167bb91b'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El curso se pasa solo. El profe es bueno, quizás no se aprende mucho, pero es fácil. Los laboratorios y proyectos quizás son un poco largos, pero no son complicados. Exámenes y quices fáciles. El profe califica todo hasta semana 18, pero si usted hizo un trabajo decente, tiene 100 fijo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '058b2aedd7744a095bbfa1dc5809d6d0d5a51cc170187445e2e888f97a2ccce4'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Todos los cursos con Harold se pasan fácil, que aprendas es otra cosa. De verdad es muy amable y buena gente, pero no se le saca el mejor provecho al curso en mi opinión.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'f2e7217ea2166f70ef1fe26a6bfb5c1a85a1717b57d50d27e1e3725fd5c49e87'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'Es súper pura vida, se pasa fácil. Los laboratorios si son algo largos pero nada complicado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '7c9412a92c34a046b8bbb33b1b62e77855a21c0d3836daf4abc7257ed62fe91b'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Es un buen profe, solo que se excede hablando por lo que hace su clase aburrida, el curso se pasa muy fácil pero entrega las notas muy tarde.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '2ab6bc6b7956b040434bba334f9b41fe18ebd5b29a190a97b8f652165340e8c7'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El profe habla muchísimo en la clase, sin embargo uno siente que no aprende, pero no es así, les recomiendo que lean de nuevo el material e investiguen y luego, conversen con el profe por mensajes, teams, consulta, entre otros, entonces, ahí va a aprender un montón.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'c5c2acae5701304b477278995dcb361f9c3fec21f13074f0278b44c77f30283e'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El profe mas vago de la vida, se pasa fácil el curso pero no se aprende nada, no sube las notas a tiempo, semana 18 y ni siquiera entrega el examen calificado, además clases super largas y aburridas donde no se aprende nada'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e1e2bde94dbd421546796824cfc2d23596426ef3d474636b1f8a1540cd7917de'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Es un profe súper mediocre e irresponsable. Si quiere pasar el curso FÁCIL meta con él, pero no se aprende nada. Tiene el cronograma de decoración porque nunca sube las asignaciones a tiempo. Termina haciendo un laboratorio que vale 30% en vez de tres, porque no le da la gana hacerlos en el semestr'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'c996f9a56c0095d111456554ab67b8839f8f7f7ca7577825b29d537eacdaf005'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El mejor profe de la escuela de producción industrial, se preocupa mucho por los estudiantes, da muy buenas clases, con él se aprende, y aunque los trabajos se llevan su rato, califica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'b03676d1e35f4184abc6149a075762dfe51815a71e415922d1ca89a853401206'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'De los mejores profes de la escuela, preocupado por los estudiantes y excelente explicando, hace exámenes largos pero califica suave, pocos quices y son bastante fáciles. Uno aprende mucho!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '128ebb7fb31767aa03dbfbedf854cfb97034040eac48b638009728dfc87ee339'::TEXT, ARRAY[1727, 1736]::BIGINT[]),
    (434::BIGINT, 'Es super vago y pasa cancelando clases. Al final uno pasa super bien pero las termina pagando porque no aprendió. Califica a como el quiera, a veces super suave o pone notas malas sin razón.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-10T00:00:00+00:00'::TIMESTAMPTZ, '246651e3ddbc5836d9a0807a99732c00c22ed4f090565cf7281781216db9b1c5'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'Puede ser un poco tedioso porque algunos temas vienen diferentes en el examen a como los explica, pero es muy buena gente y califica con amor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-12-12T00:00:00+00:00'::TIMESTAMPTZ, '9952a7249b202bcd684dcb65e7949bf311b6974992b89280d4582ef62cde61fa'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El profe es muy bueno explicando y buena persona, aunque a veces puede ser un poco vago dando las calificaciones de los trabajos. Trabajos largos y exámenes para la casa de una semana.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '763fed01cfdca6c2556710f39e4f7511b8c1e2b8ff466c9d1d0e967ce13ca0fb'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'En el curso se hacen demasiados trabajos en grupo (a veces aleatorio). Sabe mucho y lo sabe transmitir. Las clases son largas pero el intenta que uno entienda y no se haga tan aburrido con chistes y es muy respetuoso. Ayuda mucho en consulta (lo guía a uno a la solución, no solo la da).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fa70732bab2d9062ee38971a645cdd2dcc6fadc1365c1a44eb0108de9d15bff6'::TEXT, ARRAY[1727, 1736]::BIGINT[]),
    (434::BIGINT, 'Bastante malito, aburrido y no se aprende mucho. Califica a veces fácil y a veces duro, nunca se sabe.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '867e77356b0c5176006ed2b701f19952c562340788f550c9fa34559e8a01e84b'::TEXT, ARRAY[1727, 1736]::BIGINT[]),
    (434::BIGINT, 'Las clases son aburridas los labs y las tareas las califica el asistente, los examenes (son muy faciles son iguales a la practica que el da) Los avances nunca los entrega, la materia del curso es facil pero el proyecto y los labs son largos. El profe es buena gente, pero desordenado'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, '35fc912a56399b412cd3d730bfe215c01a81e6ddd877bd5768f5bc762f92ba02'::TEXT, ARRAY[1736, 1727]::BIGINT[]),
    (434::BIGINT, 'El profe explica bien y hace actividades en clase. Los exámenes no son difíciles. El 50% de su nota debe del grupo de proyecto, así que busque gente que trabaje.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-15T00:00:00+00:00'::TIMESTAMPTZ, '411db962af347329778b4f54a2b3ccfdf548a1c586707f54e2029ad5aa073e15'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'El profe explica bien. La clase se hace corta. Elijan bien a sus compañeros para el proyecto y los labs. El profe tarda bastante en entregar calificaciones de los avances del proyecto.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-07T00:00:00+00:00'::TIMESTAMPTZ, '86d0b0a0441e0ad98a10acba6b9ccc510377d28177f766046cf643c349cebb40'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Como persona, es super pura vida. Como profe es comprensivo pero su forma de enseñar deja que desear; con él de fijo se pasa pero no se aprende tanto como con otros profes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '9d32cc87178ced81d589bea9aa9ec5da1108d72a76f7ee3fd99984dca4b22193'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Si quiere aprender no meta con él. Ve lo mismo que estudio I y las clases se vuelven muy aburridas. Las rúbricas de evaluaciones son poco claras y a veces califica de forma subjetiva. Es muy fácil pasar el curso, pero no aprende nada.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'b639b58ac553d2630a467892c8df9e4fa040cddabac8a004626a72f66943a8b7'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'Super buena gente, de fijo se pasa con él. El problema fue que el curso estuvo muy flujo y fácil, en cuestión de pasar buenísimo, en aprender no tanto.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '929c707966c2f8a3c520465941bce08c0b05e202609ab42c620fe48267a4f071'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'Excelente persona y profesor, todos pasan con el. Sin embargo últimamente es muy vago, no califica casi nada sino hasta el final del semestre.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2a662bc558989140eb590e9cd6f79d28e63927011ba19a155dd094f57d1bc57f'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'El profe califica más duro pero no tiene rúbricas claras en sus exámenes. Se interesa por el estudiante y siempre está responde dudas. Además no entrega notas de nada hasta el final'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '8560f1bc357f57152080ec651f6c4a27ba8d8b28fdce1920942f093cded8e5c4'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'El curso se vuelve pesado, últimamente califica bastante duro pero es buen profe, las clases son divertidas y el se interesa muchísimo por el estudiante hay que hacer bastantes trabajos pero el es muy accesible'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'fa4e94dfcd49676e53c67563509c92831e0d1ddc94556d1ff001fedd839740d8'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'Instrucciones poco claras al momento de dejar trabajos, además calificó rudo el primer examen con una rúbrica poco clara'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '8c8cb60d1fc66292f94470baefd4b9d5e11082f39832386a061ce389d7c3b664'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'Pésimo, calificaciones sin instrucciones, se inventa la rubrica para perjudicar la nota de estudiantes. No sabe del tema, califica rudo, deja trabajos largos sin sentido, si no le agradas hace lo posible por perjudicarte. No es el mismo profesor que uno conocio. Increiblemente malo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-06-06T00:00:00+00:00'::TIMESTAMPTZ, '9475b76ea6c057eb52977dfed9826909097acdbd6adf1a95e4b42cc255c3fd14'::TEXT, ARRAY[1773]::BIGINT[]),
    (434::BIGINT, 'Explica muy bien, los exámenes son parecidos a lo que uno ve en el examen y califica normal. Como persona es excelente y también como profesor, se preocupa por el estudiante y que aprenda, hizo que me gustara más la carrera de PI.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '255592de19871f7d4e7b8f19c32508ef07b33314619da45d2e402ebf0dc2dbed'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente Profesor. Explica la materia las veces que sea necesario, hace ejemplos, tiene mucha paciencia para explicar los temas del curso. Trata de hacer dinámicas las clases. En los proyectos y exámenes califica justo. Super recomendado :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '28a3b55201671d7d55adb50180da117e184c0209cea98b435d50c10e2cefd7a1'::TEXT, ARRAY[1736]::BIGINT[]),
    (434::BIGINT, 'Muy buen profe, aunque las clases si son un poco aburridas se recomienda y el curso se pasa con entregar todo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2044033accd17164ef88727dda63df4d5173916649f0adf24c516f9605188457'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente persona y profesor; hace de su curso algo ameno y diferente. Es alguien que está siempre dispuesto a ayudar, 100% recomendado...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5a739d1b6a2ec7833bbe68b26e8223894ba35a23d480713f514c09a5469d0c5b'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, '¡Excelente persona! Espera que usted aprenda, no quebrarlo al final del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '483a4a55bcdbdc386f95515b34c5a66c628200fd7cf4c69a34bb014ac29e3922'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente profesor y persona! Realmente se aprende. Realiza exámenes largos pero no son difíciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'c0b478617af054526288d718fe993ec58b308934934b43dd312c1239298af1af'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente profesor y persona, exámenes un poco largos y teóricos pero nada fuera de lo que ha dado en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '754e2b2cff7f65cc4e0517a2f5ad579834701523f08ac9ef4880019fc54d1774'::TEXT, ARRAY[1727, 1751]::BIGINT[]),
    (434::BIGINT, 'Muy buen profesor, se aprende, es buena gente, no es de los profesores que les gusta sonar estudiantes, si no que aprendan'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '9a4aca14d1a5ca1976dbe71faaabd11e4e1de8b85ae2f7ac5e0c6adbb7e50ffa'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Algunas veces las clases son aburridas. Pero se aprende y de pasa. En Dirección no lo hace en curso pesado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'cb8cda9751341b409072bc35995a9312cf68d35b766be00f53b81cd81b8f3e2a'::TEXT, ARRAY[1727, 1751]::BIGINT[]),
    (434::BIGINT, 'Excelente profesor, todas las clases son dinámicas, y entretenidas, es MUY teorico, pero lo recomiendo 100%, se aprende mucho pues sabe mucho!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'a7b7b666306cfba692c67e2164913bedd9dd808a5fa1c98e2d60747d4254895d'::TEXT, ARRAY[1751]::BIGINT[]),
    (434::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-12T00:00:00+00:00'::TIMESTAMPTZ, '0f8f4e12eea90037f8dfe132d4c7acbee598da702cfd82273a4cb3fd2ee35e79'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '9f02f57b47587b84f997b1de62ba2dd33b40453e59f6dc1c2dd784531f41a993'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ac57134a0b5453dc070ff0457d6eb67294d03a2bbb9059ab1f5fe68e25699efc'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Un excelente profesor. Se nota la experiencia con que enseña cada contenido del curso. Debería ser más exigente con el respeto en clase, ya que hay personas que no valoran la calidad de profesor que tienen, y pasan iterrumpiedo la clase y el profesor no lo detiene. Llevaría cualquier curso con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1254412ec788d78d9f729e0d22d8bec3a676050a5d316f9660f2da3c89a61ecf'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Indudablemente, es uno de los mejores profesores de la escuela de Ingeniería en Producción Industrial. Es una excelente persona, quien se interesa por ayudarles a los demás para que salgan bien en todo. Además, se nota la gran experiencia que tiene en ciertos temas. Llévenlo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, '763d4a9df40a1a91e8ec9f89f60e91f53bb33ef4dd2dcd806317557b98151927'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Es muy buen profesor, exelente persona pero es muy poco exigente, no le da mucho seguimiento al proyecto en el transcurso del semestre y no da retroalimentación del proyecto.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'd62fb2b73a967d5376f800248a8c0eb04df1d963cb864819af23cd17b4b17da0'::TEXT, ARRAY[1736, 1727]::BIGINT[]),
    (434::BIGINT, 'Excelente profesor, se ve que ama su trabajo, las clases son dinámicas, es muy buena gente, se preocupa de los estudiantes, implementa pausas programadas durante sus clases, en general es muy buena nota'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-16T00:00:00+00:00'::TIMESTAMPTZ, '74c62a37d57f717b92f82d5fb03d028e98f9bc8ec27c20080d6ed2cdae72edda'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Es muy buen profe, a veces algo aburrido pero excelente persona y se aprende montones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'd2bbcd53893c1cd1866da4361fb7c33488538935abfab92f92477715040592ac'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente profesor, es bueno explicando y es demasiado buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-16T00:00:00+00:00'::TIMESTAMPTZ, '16580608ee99935f5919b0c06a99d0e2dcbca9d444319dca77fffa5f773b5357'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Mucha disponibilidad, ama su trabajo, es un increible profesor y muy apuntado a hacer giras y actividades, hace las clases muy dinamicas y entretenidas. Se apende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'a21a9b7607be783c904f29aa21b71f0fec14061f68f0d5548ec93d97d90f83d4'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Excelente profe y persona'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ebfbd85956323321ffc044421946226f79dd223dd45bd6c1ee12d5ed0abc245d'::TEXT, ARRAY[1727]::BIGINT[]),
    (434::BIGINT, 'Buen profesor, explica bien y es muy buena gente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, '3b464f716ef48788d17563152a25ca977a663eccf616d08046c89b5d69022713'::TEXT, ARRAY[1727]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
